def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def amount(token: str):
        if not token or any(c not in "0123456789" for c in token):
            return None
        return int(token)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False
        if verb == "open" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if n is not None and n >= 0 and name not in balances:
                balances[name] = n
                history.append(("open", name))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if n is not None and n > 0 and name in balances:
                balances[name] += n
                history.append(("deposit", name, n))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            name, n = parts[1], amount(parts[2])
            if (
                n is not None
                and n > 0
                and name in balances
                and name not in frozen
                and balances[name] >= n
            ):
                balances[name] -= n
                history.append(("withdraw", name, n))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            src, dst, n = parts[1], parts[2], amount(parts[3])
            if (
                n is not None
                and n > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= n
            ):
                balances[src] -= n
                balances[dst] += n
                history.append(("transfer", src, dst, n))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            name = parts[1]
            if name in balances and name not in frozen:
                frozen.add(name)
                history.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            name = parts[1]
            if name in balances and name in frozen:
                frozen.remove(name)
                history.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and len(parts) == 1:
            if history:
                kind = history.pop()
                if kind[0] == "open":
                    del balances[kind[1]]
                    frozen.discard(kind[1])
                elif kind[0] == "deposit":
                    balances[kind[1]] -= kind[2]
                elif kind[0] == "withdraw":
                    balances[kind[1]] += kind[2]
                elif kind[0] == "transfer":
                    balances[kind[1]] += kind[3]
                    balances[kind[2]] -= kind[3]
                elif kind[0] == "freeze":
                    frozen.remove(kind[1])
                elif kind[0] == "unfreeze":
                    frozen.add(kind[1])
                ok = True
        if not ok:
            rejected.append(i)
    return balances, rejected
